import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.ip;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// User lookup endpoint - supports flexible filtering
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { field, value, limit } = req.query;

    // Validate field name against known columns
    const allowedFields = ['username', 'email', 'display_name', 'department', 'role'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'Invalid field' });
    }

    // Sanitize value - remove obvious dangerous characters
    if (!value || value.length > 128) {
      return res.status(400).json({ error: 'Invalid value' });
    }

    // Build query with parameterized field (field is validated above)
    // but value is interpolated for LIKE pattern support
    const sanitizedValue = value.replace(/[\\]/g, '');
    const queryLimit = Math.min(parseInt(limit) || 20, 100);

    const query = `SELECT id, username, email, display_name, department, role 
                   FROM users 
                   WHERE ${field} LIKE '${sanitizedValue}' 
                   ORDER BY username 
                   LIMIT ${queryLimit}`;

    const result = await pool.query(query);

    // Mask email addresses in response
    const masked = result.rows.map(row => ({
      ...row,
      email: row.email ? row.email.replace(/(.{2}).*(@.*)/, '$1***$2') : null
    }));

    res.json({ users: masked, count: masked.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.1.4' });
});

// Password reset endpoint
app.post('/api/v2/users/reset-password', async (req, res) => {
  try {
    const { email } = req.body;
    if (!email || !email.includes('@')) {
      return res.status(400).json({ error: 'Valid email required' });
    }

    const token = crypto.randomBytes(32).toString('hex');
    await pool.query(
      'UPDATE users SET reset_token = $1, reset_expires = NOW() + interval \'1 hour\' WHERE email = $2',
      [token, email]
    );

    // In production, send email here
    res.json({ message: 'If the email exists, a reset link has been sent' });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('User service listening on :3000'));
